"use client";

import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/Card";
import { Button } from "@/components/ui/Button";
import { Input } from "@/components/ui/Input";
import { useState, useEffect } from "react";
import { getFinanceEntries } from "@/lib/data";
import { createFinanceEntryAction } from "@/lib/actions";
import { FinanceEntry } from "@/lib/types";

export default function FinancePage() {
    const [entries, setEntries] = useState<FinanceEntry[]>([]);
    const [isModalOpen, setIsModalOpen] = useState(false);

    useEffect(() => {
        getFinanceEntries().then(setEntries);
    }, []);

    const handleAdd = async (formData: FormData) => {
        await createFinanceEntryAction(formData);
        setIsModalOpen(false);
        const updated = await getFinanceEntries();
        setEntries(updated);
    };

    return (
        <div className="space-y-6">
            <div className="flex justify-between items-center">
                <h1 className="text-2xl font-bold">Finance Management</h1>
                <Button onClick={() => setIsModalOpen(true)} className="bg-teal-600 hover:bg-teal-700">
                    + Add Record
                </Button>
            </div>

            <Card>
                <CardHeader>
                    <CardTitle>Financial Records</CardTitle>
                </CardHeader>
                <CardContent>
                    <div className="space-y-4">
                        {entries.length === 0 ? (
                            <p className="text-center text-slate-500 py-10">No records found.</p>
                        ) : (
                            entries.map((entry) => (
                                <div key={entry.id} className="flex items-center justify-between p-4 border rounded-lg bg-white shadow-sm">
                                    <div>
                                        <p className="font-medium">{entry.description || entry.category}</p>
                                        <p className="text-sm text-slate-500">{entry.date}</p>
                                        <p className="text-xs text-slate-400 capitalize">{entry.category}</p>
                                    </div>
                                    <div className={entry.type === 'INCOME' ? "font-bold text-green-600" : "font-bold text-red-600"}>
                                        {entry.type === 'INCOME' ? '+' : '-'}${entry.amount.toLocaleString()}
                                    </div>
                                </div>
                            ))
                        )}
                    </div>
                </CardContent>
            </Card>

            {isModalOpen && (
                <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
                    <Card className="w-full max-w-md">
                        <CardHeader>
                            <CardTitle>Add New Record</CardTitle>
                        </CardHeader>
                        <CardContent>
                            <form action={handleAdd} className="space-y-4">
                                <div className="space-y-2">
                                    <label className="text-sm font-medium">Type</label>
                                    <select name="type" className="w-full p-2 border rounded-md" required>
                                        <option value="INCOME">Income</option>
                                        <option value="EXPENSE">Expense</option>
                                    </select>
                                </div>
                                <div className="space-y-2">
                                    <label className="text-sm font-medium">Amount ($)</label>
                                    <Input name="amount" type="number" step="0.01" required placeholder="0.00" />
                                </div>
                                <div className="space-y-2">
                                    <label className="text-sm font-medium">Category</label>
                                    <Input name="category" required placeholder="e.g. Sales, Rent, Marketing" />
                                </div>
                                <div className="space-y-2">
                                    <label className="text-sm font-medium">Description</label>
                                    <Input name="description" placeholder="Short description" />
                                </div>
                                <div className="space-y-2">
                                    <label className="text-sm font-medium">Date</label>
                                    <Input name="date" type="date" required defaultValue={new Date().toISOString().split('T')[0]} />
                                </div>
                                <div className="flex gap-2 justify-end pt-4">
                                    <Button type="button" variant="outline" onClick={() => setIsModalOpen(false)}>Cancel</Button>
                                    <Button type="submit" className="bg-teal-600">Save Record</Button>
                                </div>
                            </form>
                        </CardContent>
                    </Card>
                </div>
            )}
        </div>
    );
}
